using OricOffice.Core.Export;
using OricOffice.Core.Model;
using OricOffice.Core.Services;
using OricOffice.Core.Storage;
using OricOffice.Core.ViewModels;

namespace OricOffice.Core.Tests;

/// <summary>
/// LibreOffice import: fixtures generated by a real LibreOffice (writer8/calc8),
/// exporter→importer round-trips, and the view-model Import commands.
/// </summary>
public class OdfImportTests : IDisposable
{
    private readonly TempDir _dir = new();
    private readonly FakeDialogs _dialogs = new();
    private readonly FakeLifetime _lifetime = new();
    private readonly FakeClipboard _clipboard = new();
    private readonly OricFileStore _store;

    public OdfImportTests() => _store = new OricFileStore(_dir.Path);

    public void Dispose() => _dir.Dispose();

    private static string Fixture(string name)
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null)
        {
            var candidate = Path.Combine(dir.FullName, "fixtures", name);
            if (File.Exists(candidate)) return candidate;
            dir = dir.Parent;
        }
        throw new FileNotFoundException($"Fixture '{name}' not found under tests/fixtures.");
    }

    private AuthorViewModel CreateAuthor()
        => new(_dialogs, _lifetime, _clipboard, _store,
            new AppMeta("Oric Author", "1.0.0", OricFileKind.Author));

    private CalcViewModel CreateCalc()
        => new(_dialogs, _lifetime, _store,
            new AppMeta("Oric Calc", "1.0.0", OricFileKind.Calc));

    private static readonly byte[] TinyPng = Convert.FromBase64String(
        "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==");

    // ------------------------------------------------------------ real LibreOffice files

    [Fact]
    public void RealLibreOfficeOdt_ImportsParagraphsInDocumentOrder()
    {
        var doc = OdfImporter.Import(Fixture("lb-sample.odt"));

        var lines = doc.Text.Body.Split('\n');
        Assert.Equal(3, lines.Length);
        Assert.Equal("LibreOffice Writer sample document.", lines[0]);
        Assert.Equal("Imported paragraphs must land in document order.", lines[1]);
        Assert.Equal("Third line proves plain text survives the trip.", lines[2]);
    }

    [Fact]
    public void RealLibreOfficeOds_ImportsTypedCells()
    {
        var doc = OdfImporter.Import(Fixture("lb-sample.ods"));

        Assert.Equal("Item", doc.Sheet.RawAt(0, 0));
        Assert.Equal("Price", doc.Sheet.RawAt(0, 1));
        Assert.Equal("Apples", doc.Sheet.RawAt(1, 0));
        Assert.Equal("12.5", doc.Sheet.ValueAt(1, 1));
        Assert.Equal("42.5", doc.Sheet.ValueAt(3, 1));
        Assert.True(doc.Sheet.RowCount >= 4);
        Assert.True(doc.Sheet.ColumnCount >= 2);
    }

    // ------------------------------------------------------------ round-trips

    [Fact]
    public void Odt_RoundTripsThroughOurExporter_WithTextImageAndTable()
    {
        var source = OricFile.CreateNew(OricFileKind.Author, "Round Trip");
        source.Text.Body = "First line.\n\nSecond line.";
        source.Text.Images.Add(new DocumentImage("logo.png", TinyPng));
        var table = new TableBlock("Grid", 2, 2);
        table.SetText(0, 0, "Head");
        table.SetFill(0, 0, "#FFF2CC");
        table.SetText(1, 1, "Tail");
        source.Text.Tables.Add(table);

        var path = _dir.File("round" + OricFileKind.Author.For());
        OdfExporter.ExportOdt(source, path);
        var back = OdfImporter.ImportOdt(path);

        Assert.Equal(source.Text.Body, back.Text.Body);
        Assert.Single(back.Text.Images);
        Assert.Equal(ImageFormat.Png, back.Text.Images[0].Format);
        var backTable = Assert.Single(back.Text.Tables);
        Assert.Equal("Grid", backTable.Name);
        Assert.Equal("Head", backTable.TextAt(0, 0));
        Assert.Equal("#FFF2CC", backTable.FillAt(0, 0));
        Assert.Equal("Tail", backTable.TextAt(1, 1));
    }

    [Fact]
    public void Ods_RoundTripsThroughOurExporter_WithLiteralsAndFormula()
    {
        var source = OricFile.CreateNew(OricFileKind.Calc, "Calc Round Trip");
        source.Sheet.Set(0, 0, "Item", "Item");
        source.Sheet.Set(1, 0, "Apples", "Apples");
        source.Sheet.Set(1, 1, "12.5", "12.5");
        source.Sheet.Set(3, 1, "=SUM(B2:B3)", "42.5");

        var path = _dir.File("round" + OricFileKind.Calc.For());
        OdfExporter.ExportOds(source, path);
        var back = OdfImporter.ImportOds(path);

        Assert.Equal("Item", back.Sheet.RawAt(0, 0));
        Assert.Equal("12.5", back.Sheet.ValueAt(1, 1));
        Assert.Equal("=SUM(B2:B3)", back.Sheet.RawAt(3, 1));
        Assert.Equal("42.5", back.Sheet.ValueAt(3, 1));
    }

    [Fact]
    public void ReverseTransformFormula_HandlesRelativeAndAbsoluteRanges()
    {
        Assert.Equal("SUM(B2:B3)", OdfImporter.ReverseTransformFormula("of:=SUM([.B2:.B3])"));
        Assert.Equal("SUM(B2:B3)", OdfImporter.ReverseTransformFormula("of:=SUM([.$B$2:.$B$3])"));
        Assert.Equal("A1+1", OdfImporter.ReverseTransformFormula("of:=[.A1]+1"));
        Assert.Equal("1+1", OdfImporter.ReverseTransformFormula("=1+1"));
    }

    // ------------------------------------------------------------ view-model commands

    [Fact]
    public async Task AuthorImportCommand_LoadsLibreOfficeWriterFile()
    {
        var vm = CreateAuthor();
        _dialogs.OpenPath = Fixture("lb-sample.odt");

        await vm.ImportOdtCommand.ExecuteAsync(null);

        Assert.Contains("LibreOffice Writer sample document", vm.Body);
        Assert.Null(vm.FilePath); // imported, not adopted as a save target
        Assert.False(vm.IsDirty);
        Assert.StartsWith("Imported", vm.StatusText);
        Assert.Empty(_dialogs.Messages);
    }

    [Fact]
    public async Task CalcImportCommand_LoadsLibreOfficeCalcFile()
    {
        var vm = CreateCalc();
        _dialogs.OpenPath = Fixture("lb-sample.ods");

        await vm.ImportOdsCommand.ExecuteAsync(null);

        Assert.Equal("Apples", vm.CellAt(1, 0).Display);
        Assert.Equal("12.5", vm.CellAt(1, 1).Display);
        Assert.False(vm.IsDirty);
        Assert.StartsWith("Imported", vm.StatusText);
    }

    [Fact]
    public async Task ImportCommand_RejectsNonOdfFiles_WithClearMessage()
    {
        var vm = CreateAuthor();
        _dialogs.OpenPath = Fixture("author.oau"); // SQLite, not an ODF package
        vm.Body = "current work";

        await vm.ImportOdtCommand.ExecuteAsync(null);

        Assert.Equal("current work", vm.Body); // untouched
        Assert.Contains(_dialogs.Messages, m => m.Title == "Import failed");
    }

    [Fact]
    public async Task ImportCommand_Cancelled_DoesNothing()
    {
        var vm = CreateAuthor();
        vm.Body = "keep me"; // marks the document dirty
        _dialogs.OpenPath = null; // user cancels the picker

        await vm.ImportOdtCommand.ExecuteAsync(null);

        // Cancellation leaves the working document exactly as it was.
        Assert.Equal("keep me", vm.Body);
        Assert.True(vm.IsDirty);
        Assert.Equal(vm.StatsText, vm.StatusText); // status still shows the live word count
    }
}
